const current=()=>db.users.find(u=>u.id===sessionStorage.getItem('luutru-user')),plan=u=>db.plans.find(p=>p.id===u.plan),used=u=>db.files.filter(f=>f.owner===u.id).reduce((n,f)=>n+f.bytes,0),user=id=>db.users.find(u=>u.id===id),file=id=>db.files.find(f=>f.id===id),avatar=u=>u.avatar?`<img class="avatar" src="${esc(u.avatar)}" alt="Ảnh đại diện">`:`<span class="avatar">${esc(u.name.split(' ').slice(-2).map(x=>x[0]).join(''))}</span>`,price=p=>Math.round(p.price*(1-(p.until&&new Date(p.until+'T23:59:59').getTime()>=Date.now()?p.discount:0)/100));
let idbPromise;function blobDB(){return idbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('luutru-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}async function blobs(action,id,value){const d=await blobDB();return new Promise((resolve,reject)=>{const t=d.transaction('files',action==='get'?'readonly':'readwrite');const r=t.objectStore('files')[action](...(action==='put'?[value,id]:[id]));let result;r.onsuccess=()=>result=r.result;t.oncomplete=()=>resolve(result);t.onerror=()=>reject(t.error)})}
function purge(){const expired=new Set(db.files.filter(f=>f.deleted&&Date.now()-f.deleted>=30*864e5).map(f=>f.id));if(expired.size){db.files=db.files.filter(f=>!expired.has(f.id));expired.forEach(id=>blobs('delete',id).catch(()=>{}));save()}}purge();setInterval(purge,60000);
