function modal(title,html,submit){if(previewURL){URL.revokeObjectURL(previewURL);previewURL=null}const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="iconbtn" type="button" aria-label="Đóng" onclick="closeModal()">${icon('close')}</button></div><div class="dialog-body">${html}</div>`;if(!d.open)d.showModal();const f=d.querySelector('form');if(f&&submit)f.onsubmit=async e=>{e.preventDefault();try{await submit(new FormData(f),f)}catch(err){toast(err.message||'Thao tác không thành công. Vui lòng thử lại.')}}}
